// Two variable definitions
const v = [600, 625, 650, 675, 700, 725, 750, 775, 800, 825, 850, 875, 900];
const c1 = OLI.random(0,12,0);
const vol = v[c1] .toPrecision(3);

const c = [0.2, 0.25, 0.3, 0.35, 0.4, 0.45, 0.5];
const c2 = OLI.random(0,6,0);
const conc = c[c2] .toPrecision(3);
const grams = OLI.random(2,5,3);

const molnaoh = grams/40;
const molnaohsf = molnaoh .toPrecision(3);
const molhno2 = conc*vol/1000;
const molhno2sf = molhno2 .toPrecision(3);
const molacid = molhno2-molnaoh;
const molacidsf = molacid .toPrecision(3);
const ka = 7.2e-4;
const pka = -Math.log10(ka);
const ratio = molnaoh/molacid;
const ph = pka + Math.log10(molnaoh/molacid);
const phsf = ph .toPrecision(3);

const phlow = 0.99*ph;
const phhigh = 1.01*ph;

// Expose variables to OLI
module.exports = {
   grams, conc, vol, molnaohsf, molhno2sf, molacidsf, ratio, ph, phsf, phlow, phhigh
};
